          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_get_cell",
      "description": "Read one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_load",
      "description": "Load a sample into an instrument",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer",
            "description": "Sample slot 0..15"
          }
        },
        "required": [
          "path",
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_save",
      "description": "Save the current module",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "format": {
            "type": "string",
            "enum": [
              "xm",
              "mod"
            ]
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_render",
      "description": "Render the current module to WAV",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "rate": {
            "type": "integer"
          },
          "bits": {
            "type": "integer"
          },
