import wave, numpy as np
with wave.open('/workspace/work/neon_cipher_v2.wav','rb') as w:
    sr=w.getframerate(); x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(np.float32).reshape(-1,2).mean(1)
def bands(seg):
    sp=np.abs(np.fft.rfft(seg*np.hanning(len(seg))))**2
    f=np.fft.rfftfreq(len(seg),1/sr)
    out=[]
