{"command":"cd /workspace && python3 - <<'PY'
# Extract lead (ch6) and harmony (ch7) note events from v7.xm for review
import struct
b=open('/workspace/work/neon_cipher_v7.xm','rb').read()
hs=struct.unpack_from('<I',b,60)[0]
songlen,restart,chans,pats,inss,flags,tempo,bpm=struct.unpack_from('<8H',b,64)
off=60+hs
names=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def nname(n):
    if n==97: return 'OFF'
    if n==0: return '-'
    n-=1; o=n//12; s=n%12
    return f'{names[s]}{o}'
for p in range(pats):
    hdr=struct.unpack_from('<I',b,off)[0]; rows=struct.unpack_from('<H',b,off+5)[0]; packed=struct.unpack_from('<H',b,off+7)[0]
    data=b[off+hdr:off+hdr+packed]; pos=0; cells={}
    for row in range(rows):
        for ch in range(chans):
            note=ins=vol=eff=par=0
            if pos<len(data):
                d=data[pos]; pos+=1
                if d&0x80:
                    if d&1: note=data[pos]; pos+=1
                    if d&2: ins=data[pos]; pos+=1
                    if d&4: vol=data[pos]; pos+=1
                    if d&8: eff=data[pos]; pos+=1; par=data[pos]; pos+=1
                else:
                    note=d; ins=data[pos]; pos+=1; vol=data[pos]; pos+=1; eff=data[pos]; pos+=1; par=data[pos]; pos+=1
            if note or ins or vol or eff or par: cells[(row,ch)]=(note,ins,vol,eff,par)
    off+=hdr+packed
    print('\nPATTERN',p)
    for ch in [6,7]:
        ev=[]
        for row in range(64):
            if (row,ch) in cells and cells[(row,ch)][0]:
                ev.append((row,nname(cells[(row,ch)][0]),cells[(row,ch)][2]))
        print(' ch',ch,ev)
PY"}

